/usr/bin/python3 -I -B -c 'import hashlib,json,os,pwd,sys,subprocess
from pathlib import Path
try:
 payload=json.load(sys.stdin)
 cwd=payload.get("cwd")
 if not isinstance(cwd,str) or not os.path.isabs(cwd): sys.exit(2)
 env={"PATH":"/usr/bin:/bin","HOME":pwd.getpwuid(os.getuid()).pw_dir,"GIT_CONFIG_GLOBAL":"/dev/null","GIT_CONFIG_NOSYSTEM":"1","GIT_NO_REPLACE_OBJECTS":"1","GIT_TERMINAL_PROMPT":"0"}
 root=subprocess.run(["/usr/bin/git","-C",cwd,"rev-parse","--show-toplevel"],env=env,capture_output=True,text=True)
 if root.returncode:
  if any(os.path.lexists(p/".git") for p in (Path(cwd),*Path(cwd).parents)): sys.exit(2)
  sys.exit(0)
 repo=Path(root.stdout.strip())
 if not os.path.lexists(repo/".codex-gate.yaml"):
  committed=subprocess.run(["/usr/bin/git","-C",str(repo),"ls-tree","HEAD","--",".codex-gate.yaml"],env=env,capture_output=True,text=True)
  if committed.returncode==0 and not committed.stdout.strip(): sys.exit(0)
  refs=subprocess.run(["/usr/bin/git","-C",str(repo),"show-ref","--head"],env=env,capture_output=True,text=True)
  if refs.returncode in (0,1) and not refs.stdout.strip() and not refs.stderr.strip(): sys.exit(0)
  if committed.returncode: sys.exit(2)
 p=pwd.getpwuid(os.getuid()).pw_dir+"/.local/lib/claude-gates/native_hook.py"
 d=open(p,"rb").read()
 if hashlib.sha256(d).hexdigest()!="696b0b8c98e6f16d1f2c461babf5e0f84c3759e4cf54a246c7039890c65fda13": sys.exit(2)
except Exception:
 sys.exit(2)
sys.argv=[p]+sys.argv[1:]
exec(compile(d,p,"exec"),{"__name__":"__main__","__file__":p})' codex_review_gate.py gate-edit

